/* Operational data contract and source-aware business views. No embedded credentials. */
const completionKey='lifescience.connections.v1';
let completion={records:{},connections:{},documents:[]};
try{const v=JSON.parse(localStorage.getItem(completionKey)||'null');if(v&&typeof v==='object')completion={...completion,...v}}catch{}
const factoryCodes=['CAI','DEL','ALX','SUE'];
function saveCompletion(){try{localStorage.setItem(completionKey,JSON.stringify(completion))}catch{openModal('Storage full','Export your operational data before importing another large file.')}}
function recordFor(fi=factoryIndex()){const r=completion.records[fi];return r&&r.period===($('#period').value||'Today')?r:null}
function sourceState(fi=factoryIndex()){const r=recordFor(fi),c=completion.connections[fi];if(!r)return {label:'Demo',stale:false};const stale=Date.now()-Date.parse(r.observedAt)>15*60*1000;return {label:c?.error?'Connection error / last record':r.origin==='gateway'?'Gateway data':'Imported data',stale,time:r.observedAt}}
function validateOperations(raw){
 const r=JSON.parse(JSON.stringify(raw));const fail=s=>{throw Error(s)};const num=(v,min,max,label)=>{if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max)fail(label+' is outside its accepted range')};const id=v=>{if(typeof v!=='string'||!/^[-A-Za-z0-9_]{1,70}$/.test(v))fail('IDs must use letters, numbers, dashes or underscores')};const text=(v,label)=>{if(typeof v!=='string'||!v.trim()||v.length>500||/[<>]/.test(v))fail(label+' is missing or too long')};const list=(v,name,max=200)=>{if(!Array.isArray(v)||v.length>max)fail(name+' must be an array with at most '+max+' rows');return v};
 const inspect=v=>{if(typeof v==='string'&&(/[<>]/.test(v)||v.length>2000))fail('Text fields cannot contain markup and must be under 2000 characters');if(v&&typeof v==='object')for(const [k,x] of Object.entries(v)){if(['__proto__','constructor','prototype'].includes(k))fail('Unsupported field');inspect(x)}};inspect(r);
 if(r.schemaVersion!==1)fail('schemaVersion must be 1');num(r.factory,0,3,'Factory');if(!Number.isInteger(r.factory))fail('Factory must be an integer');if(!['Today','This week','This month'].includes(r.period))fail('Choose a supported period');if(!Number.isFinite(Date.parse(r.observedAt))||Date.parse(r.observedAt)>Date.now()+300000)fail('observedAt must be a valid timestamp, not in the future');text(r.source,'Source');
 let sections=0;

 const named=(value,name,length,max=1e12)=>{list(value,name,length);if(value.length!==length)fail(name+' must have '+length+' entries');value.forEach(row=>{text(row.name,name+' name');num(row.value,0,max,name+' value')})};
 const series=(value,name,length,max=1e12)=>{list(value,name,48);if(value.length!==length)fail(name+' length must match labels');value.forEach(v=>num(v,0,max,name))};
 if(r.kpis){sections++;const k=r.kpis;if(!r.business||!['quality','satisfaction','compliance','recall','legal','delivery','supplier','defect','cost','downtime'].every(key=>typeof r.business[key]==='number'))fail('KPI breakdowns need the business summary metrics');named(k.qualityByProduct,'Product quality',3,100);series(k.sentiment,'Satisfaction shares',4,100);if(Math.abs(k.sentiment.reduce((a,b)=>a+b,0)-100)>.1)fail('Satisfaction shares must total 100%');list(k.ratings,'Ratings',7);if(k.ratings.length!==7)fail('Provide seven product ratings');k.ratings.forEach(v=>{text(v.name,'Product name');num(v.score,0,5,'Rating');num(v.reviews,0,1e9,'Review count')});num(k.onTime,0,1e9,'On-time orders');num(k.late,0,1e9,'Late orders');named(k.warranty,'Warranty claims',5);named(k.complaints,'Complaints',5);named(k.supplierTrend,'Supplier trend',6,100);named(k.defectByLine,'Defect rate',3,100);named(k.costBreakdown,'Poor quality costs',4);named(k.downtime,'Downtime',5)}
 if(r.sustainability){sections++;const s=r.sustainability;list(s.labels,'Sustainability labels',48);if(s.labels.length<2)fail('Supply at least two period labels');s.labels.forEach(v=>text(v,'Period label'));for(const k of ['energy','energyCost','emissions'])series(s[k],k,s.labels.length);for(const k of ['waterReuse','wasteRecovery'])series(s[k],k,s.labels.length,100);named(s.waterWithdrawal,'Water withdrawal',4);named(s.emissionSources,'Emission sources',3);named(s.wasteStreams,'Waste streams',4)}
 if(r.supplyChain){sections++;const s=r.supplyChain;num(s.delivery,0,100,'On-time delivery');num(s.inventoryCoverageDays,0,1e5,'Inventory coverage');num(s.supplierQuality,0,100,'Supplier quality');list(s.labels,'Supply labels',48);if(s.labels.length<2)fail('Supply at least two trend labels');s.labels.forEach(v=>text(v,'Supply period'));series(s.deliveryTrend,'Delivery trend',s.labels.length,100);series(s.supplierQualityTrend,'Supplier quality trend',s.labels.length,100);list(s.materials,'Materials',200).forEach(m=>{text(m.name,'Material');text(m.unit,'Material unit');num(m.onHand,0,1e12,'On-hand quantity');num(m.coverageDays,0,1e5,'Coverage');text(m.status,'Material status')});list(s.orders,'Orders',200).forEach(o=>{id(o.id);text(o.customer,'Customer');if(!Number.isFinite(Date.parse(o.due)))fail('Invalid order due date');num(o.units,0,1e12,'Order quantity');text(o.status,'Order status');if(typeof o.atRisk!=='boolean')fail('atRisk must be boolean')})}
 if(r.business){sections++;for(const [k,v] of Object.entries(r.business)){if(!Object.keys(snapshots[0]).includes(k))fail("Unknown business metric: "+k);num(v,0,["cost","downtime","legal"].includes(k)?1e9:100,k)}}
 if(r.production){sections++;list(r.production.lines,'Production lines',3).forEach(l=>{num(l.index,0,2,'Line');if(!Number.isInteger(l.index))fail('Line index must be an integer');text(l.product,'Product');text(l.workOrder,'Work order');num(l.target,1,1e12,'Target');num(l.output,0,1e12,'Output');num(l.plannedMinutes,1,1e7,'Planned minutes');num(l.runMinutes,0,l.plannedMinutes,'Run minutes');for(const k of ['availability','performance','quality','reject','progress'])num(l[k],0,100,k);if(!['Running','Stopped','Changeover'].includes(l.status))fail('Unknown line status')});if(new Set(r.production.lines.map(l=>l.index)).size!==r.production.lines.length)fail('Duplicate line index')}
 if(r.assets){sections++;list(r.assets,'Assets',4).forEach(a=>{num(a.index,0,3,'Asset index');if(!Number.isInteger(a.index))fail('Asset index must be an integer');id(a.id);num(a.health,0,100,'Health');if(a.cost!=null)num(a.cost,0,1e12,'Value at risk');num(a.value,0,1e8,'Condition');num(a.limit,.00001,1e8,'Condition limit');num(a.hours,0,1e8,'Run hours');if(a.skill)text(a.skill,'Required skill');text(a.unit,'Unit');text(a.label,'Condition label');text(a.secondary,'Secondary reading');list(a.samples,'Condition samples',500).forEach(p=>{num(p.value,0,1e8,'Sample value');if(!Number.isFinite(Date.parse(p.time)))fail('Invalid sample timestamp')});const ts=a.samples.map(p=>Date.parse(p.time));if(ts.some((t,i)=>i&&t<=ts[i-1]))fail('Samples must have unique, increasing timestamps');if(ts.some(t=>t>Date.parse(r.observedAt)))fail('Samples cannot be newer than observedAt')});if(new Set(r.assets.map(a=>a.index)).size!==r.assets.length||new Set(r.assets.map(a=>a.id)).size!==r.assets.length)fail('Duplicate asset index or ID')}
 if(r.facility){sections++;list(r.facility,'Facility measures',30).forEach(m=>{text(m.name,'Measure');num(m.value,-1e8,1e8,'Facility value');text(m.unit,'Unit');num(m.min,-1e8,1e8,'Minimum');num(m.max,m.min,1e8,'Maximum')})}
 if(r.quality){sections++;const q=r.quality;if(q.cip){text(q.cip.recipe,'CIP recipe');text(q.cip.asset,'CIP asset');text(q.cip.phase,'CIP phase');if(!['Running','Complete','Held'].includes(q.cip.status))fail('Unknown CIP status');num(q.cip.temperature,-100,300,'CIP temperature');num(q.cip.flow,0,1e6,'CIP flow');num(q.cip.conductivity,0,1e6,'Conductivity');const lim=q.cip.limits;if(!lim)fail('CIP phase acceptance limits are required');num(lim.temperatureMin,-100,300,'CIP minimum temperature');num(lim.temperatureMax,lim.temperatureMin,300,'CIP maximum temperature');num(lim.flowMin,0,1e6,'CIP minimum flow');num(lim.conductivityMax,0,1e6,'CIP maximum conductivity');if(q.cip.history)list(q.cip.history,'CIP history',200).forEach(h=>{if(!Number.isFinite(Date.parse(h.time)))fail('Invalid CIP history timestamp');text(h.phase,'History phase');text(h.result,'History result')});}if(q.pat)list(q.pat,'PAT',20).forEach(m=>{text(m.name,'PAT measure');num(m.value,-1e8,1e8,'PAT value');text(m.unit,'Unit');num(m.min,-1e8,1e8,'PAT minimum');num(m.max,m.min,1e8,'PAT maximum')});if(!q.cip&&!q.pat)fail('Quality needs CIP or PAT readings')}
 if(r.batches){sections++;list(r.batches,'Batches').forEach(b=>{id(b.id);num(b.line,0,2,'Batch line');num(b.stage,0,4,'Batch stage');if(!Number.isInteger(b.line)||!Number.isInteger(b.stage))fail('Invalid batch line or stage');num(b.progress,0,100,'Batch progress');num(b.units,0,1e12,'Batch units');text(b.product,'Batch product');if(!['Queued','Running','Held','Ready','Complete'].includes(b.status))fail('Unknown batch status');b.factory=r.factory});if(new Set(r.batches.map(b=>b.id)).size!==r.batches.length)fail('Duplicate batch ID')}
 if(r.alarms){sections++;list(r.alarms,'Alarms').forEach(a=>{id(a.id);for(const k of ['area','title','impact','asset','reading'])text(a[k],k);if(!['High','Medium','Low'].includes(a.severity))fail('Unknown severity');if(!['Open','Acknowledged','Resolved'].includes(a.status))fail('Unknown alarm status');if(!Number.isFinite(Date.parse(a.time)))fail('Invalid alarm timestamp');a.factory=r.factory});if(new Set(r.alarms.map(a=>a.id)).size!==r.alarms.length)fail('Duplicate alarm ID')}
 if(r.workOrders){sections++;list(r.workOrders,'Work orders',200).forEach(w=>{id(w.id);id(w.assetId);if(!r.assets?.some(a=>a.id===w.assetId))fail('Work orders need a matching asset record');if(!['Open','Assigned','Completed'].includes(w.status))fail('Invalid work-order status');if(w.assignee&&!r.workforce?.some(p=>p.id===w.assignee))fail('Work order technician is not in the supplied roster');if(w.note)text(w.note,'Work instructions');if(w.events)list(w.events,'Work events',200).forEach(e=>{if(!Number.isFinite(Date.parse(e.time)))fail('Invalid event timestamp');text(e.message,'Work event')})});if(new Set(r.workOrders.map(w=>w.id)).size!==r.workOrders.length)fail('Duplicate work-order ID')}
 if(r.workforce){sections++;list(r.workforce,'Workforce',100).forEach(p=>{id(p.id);text(p.name,'Person name');text(p.role,'Role');list(p.skills,'Skills',20).forEach(s=>text(s,'Skill'));if(!/^\d{4}-\d{2}-\d{2}$/.test(p.expiry)||!Number.isFinite(Date.parse(p.expiry)))fail('Qualification expiry must be an ISO date');p.valid=Date.parse(p.expiry+'T23:59:59Z')>=Date.now()});if(new Set(r.workforce.map(p=>p.id)).size!==r.workforce.length)fail('Duplicate technician ID')}
 for(const [other,existing] of Object.entries(completion.records)){if(+other===r.factory)continue;for(const section of ['assets','batches','alarms'])if(r[section]?.some(row=>existing[section]?.some(old=>old.id===row.id)))fail('IDs must be unique across factories: '+section)}
 if(!sections)fail('Include at least one operational section');return r;
}
function applyOperations(raw,origin='import'){const r=validateOperations(raw);if(origin==='gateway'&&completion.records[r.factory]?.period===r.period&&Date.parse(completion.records[r.factory].observedAt)>Date.parse(r.observedAt))throw Error('Gateway returned an older snapshot');r.origin=origin;completion.records[r.factory]=r;saveCompletion();return r}
function assetFor(fi,index){const base=assets[index],input=recordFor(fi)?.assets?.find(a=>a.index===index);const h=[[88,97,92,81],[93,94,86,75],[78,96,89,62],[91,92,84,72]][fi][index];const c=conditionFor(fi,index);return {...base,id:factoryCodes[fi]+'-'+base.id,health:h,cost:Math.round(base.cost*(.8+fi*.12)),risk:h<70?'Critical inspection':h<90?'Inspection recommended':'Healthy',...(input?{id:input.id,health:input.health,cost:input.cost??0,skill:input.skill||base.skill,risk:input.health<70?'Critical inspection':input.health<90?'Inspection recommended':'Healthy'}:{}),reading:c.label+' '+c.value+' '+c.unit,target:c.label+' upper limit '+c.limit+' '+c.unit}}
function conditionFor(fi,index){const base=maintCondition[index],input=recordFor(fi)?.assets?.find(a=>a.index===index);if(input)return {...base,...input,series:input.samples.map(s=>s.value),samples:input.samples,source:recordFor(fi).source};const delta=[-.5,-.8,0,-.3][fi];const series=base.series.map(v=>+(Math.max(0,v+delta)).toFixed(2));const end=Date.now();return {...base,value:series.at(-1),secondary:index===0?(64+fi*2)+' °C':base.secondary,hours:base.hours+fi*713,series,samples:series.map((value,i)=>({time:new Date(end-(series.length-1-i)*4*3600000).toISOString(),value})),source:'Demonstration samples'}}
function thresholdForecast(samples,limit){if(samples.length<5)return {status:'Insufficient history',note:'At least five timestamped measurements are required.'};const t0=Date.parse(samples[0].time),xs=samples.map(s=>(Date.parse(s.time)-t0)/3600000),ys=samples.map(s=>s.value),n=xs.length,mx=xs.reduce((a,b)=>a+b,0)/n,my=ys.reduce((a,b)=>a+b,0)/n,sxx=xs.reduce((a,x)=>a+(x-mx)**2,0);if(!sxx)return {status:'Insufficient history'};const slope=xs.reduce((a,x,i)=>a+(x-mx)*(ys[i]-my),0)/sxx,intercept=my-slope*mx,sse=xs.reduce((a,x,i)=>a+(ys[i]-(intercept+slope*x))**2,0),sst=ys.reduce((a,y)=>a+(y-my)**2,0),r2=sst?Math.max(0,1-sse/sst):1,last=ys.at(-1),prediction=intercept+slope*(xs.at(-1)+24),rmse=Math.sqrt(sse/Math.max(1,n-2));return {status:last>=limit?'Limit exceeded':slope<=0?'Stable or improving':r2<.5?'Unreliable trend':'Rising trend',slope,r2,rmse,prediction,hours:last>=limit?0:slope>0&&r2>=.5?Math.max(0,(limit-(intercept+slope*xs.at(-1)))/slope):null,n,limit}}
function peopleFor(fi){const source=recordFor(fi)?.workforce;return source?source.map(p=>({...p,valid:Date.parse(p.expiry+'T23:59:59Z')>=Date.now()})):people}
function integrationTemplate(fi=factoryIndex()){const observedAt=new Date().toISOString();return {schemaVersion:1,factory:fi,period:'Today',source:'Replace with your source system name',observedAt,business:{...snapshots[fi]},production:{lines:lineSpecs.map((l,index)=>({...l,index,workOrder:'WO-'+factoryCodes[fi]+'-'+index,plannedMinutes:480,runMinutes:Math.round(480*l.utilization/100)}))},assets:assets.map((a,index)=>{const c=conditionFor(fi,index);return {index,id:factoryCodes[fi]+'-'+a.id,health:assetFor(fi,index).health,cost:assetFor(fi,index).cost,skill:a.skill,label:c.label,value:c.value,limit:c.limit,unit:c.unit,secondary:c.secondary,hours:c.hours,samples:c.samples.map(p=>({...p,time:new Date(Math.min(Date.parse(p.time),Date.parse(observedAt))).toISOString()}))}}),facility:[{name:'Cleanroom temperature',value:21.4,unit:'°C',min:20,max:24},{name:'Power demand',value:1.24,unit:'MW',min:0,max:1.4}],quality:{cip:{asset:'CIP-01',recipe:'CLN-04',phase:'Caustic wash',status:'Running',temperature:78,flow:17,conductivity:.7,limits:{temperatureMin:75,temperatureMax:85,flowMin:15,conductivityMax:1},history:[]},pat:[{name:'Assay',value:99.2,unit:'%',min:98,max:102},{name:'Moisture',value:2.1,unit:'%',min:0,max:2.5}]},batches:scopedBatches(true).filter(b=>b.factory===fi),alarms:demoAlarms.filter(a=>a.factory===fi).map(a=>({...a,time:observedAt,status:'Open'})),workforce:people.map(p=>({...p,expiry:p.valid?'2027-12-31':'2025-01-01'}))}}
function downloadOperationsTemplate(){downloadable('factory-data-contract.json',JSON.stringify(integrationTemplate(),null,2),'application/json')}
function exportOperations(){downloadable('factory-records.json',JSON.stringify(completion.records,null,2),'application/json')}
function connectionView(){return `<section class="panel connections-workspace"><div class="panelhead"><div><h2>Connections & operational records</h2><small>Bring factory data and approved documents into one business view.</small></div><div class="actions">${opButton('Data template','downloadOperationsTemplate()')}${opButton('Documents','realDocumentCenter()')}${opButton('Site layout','siteLayoutCenter()')}</div></div><div class="connection-sites">${factories.map((f,i)=>{const s=sourceState(i),r=recordFor(i),c=completion.connections[i]||{};return `<article><h3>${escapeHTML(f.name)}</h3><span class="pill ${s.stale?'amber-pill':''}">${s.label}${s.stale?' · Stale':''}</span><p>${r?escapeHTML(r.source)+'<br>'+escapeHTML(r.observedAt):'No operational source supplied. Views use labeled demonstration data.'}</p><p>${r?['production','assets','facility','quality','batches','alarms','workforce','workOrders','kpis','sustainability','supplyChain'].filter(k=>r[k]).join(' · '):'Import a JSON snapshot or connect your authenticated HTTPS gateway.'}</p><div class="actions">${opButton('Import data',`importOperationsFile(${i})`)}${opButton('Connect',`configureConnection(${i})`)}${c.url?opButton('Refresh',`refreshConnection(${i})`):''}${r?opButton('Inspect record',`inspectOperations(${i})`):''}</div><small>${escapeHTML(c.error||'')}</small></article>`}).join('')}</div><div class="connection-footer"><span>Uploads stay in this browser. Gateway records are source timestamps, not automatically verified plant data.</span>${opButton('Export records','exportOperations()')}</div></section>`}
function importOperationsFile(fi){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2000000)throw Error('Maximum snapshot size is 2 MB');const data=JSON.parse(await file.text());if(data.factory!==fi)throw Error('File factory does not match selected site');applyOperations(data);render();openModal('Factory data imported',`<p>${escapeHTML(factories[fi].name)} · ${escapeHTML(data.source)}</p><p>Imported readings now populate their matching period and operational views. Missing sections remain clearly labeled demo data.</p>`)}catch(e){openModal('Import rejected',escapeHTML(e.message))}};input.click()}
function inspectOperations(fi){const r=recordFor(fi);openModal('Source record',`<div class="scope-label">${escapeHTML(factories[fi].name)} · ${escapeHTML(r?.observedAt||'No matching period')}</div><pre class="connection-json">${escapeHTML(JSON.stringify(r,null,2))}</pre>`)}
function connectionURL(value){const u=new URL(value);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw Error('Use HTTPS, or localhost for development');if(u.username||u.password||u.search||u.hash)throw Error('Do not include credentials, query secrets or fragments');return u.href.replace(/\/$/,'')}
function configureConnection(fi){const c=completion.connections[fi]||{};openModal('Connect '+factories[fi].name,`<p>Use an authenticated gateway serving the dashboard data contract. Credentials stay at the gateway; browser session cookies are used.</p><label>Factory gateway base URL<input id="gateway-url" type="url" placeholder="https://operations.example/api/factories/${fi}" value="${escapeHTML(c.url||'')}"></label><label class="connection-check"><input id="gateway-poll" type="checkbox" ${c.poll?'checked':''}> Refresh every 30 seconds while this dashboard is open</label><label class="connection-check"><input id="gateway-control" type="checkbox" ${c.control?'checked':''}> Enable command requests through this gateway</label><p>Read: GET /snapshot · Write: POST /commands. Requests require CORS support. The gateway enforces identity, permissions and equipment interlocks.</p><div class="actions">${opButton('Save & test',`saveConnection(${fi})`)}${c.url?opButton('Disconnect',`disconnectOperations(${fi})`):''}</div><div id="connection-feedback"></div>`)}
async function saveConnection(fi){try{const url=connectionURL($('#gateway-url').value);completion.connections[fi]={url,poll:!!$('#gateway-poll').checked,control:!!$('#gateway-control').checked};saveCompletion();await refreshConnection(fi);render();configureConnection(fi)}catch(e){$('#connection-feedback').textContent=e.message}}
function disconnectOperations(fi){delete completion.connections[fi];delete completion.records[fi];saveCompletion();render();openModal('Disconnected','This factory has returned to its labeled demonstration data. Uploaded documents are retained.')}
async function refreshConnection(fi){const c=completion.connections[fi];if(!c)return;try{const res=await fetch(c.url+'/snapshot',{credentials:'include',signal:AbortSignal.timeout(10000)});if(!res.ok)throw Error('Gateway returned HTTP '+res.status);const text=await res.text();if(text.length>2000000)throw Error('Snapshot exceeds 2 MB');const r=JSON.parse(text);if(r.factory!==fi)throw Error('Wrong factory in response');applyOperations(r,'gateway');c.error='';c.lastSuccess=new Date().toISOString()}catch(e){c.error=e.message}saveCompletion();render()}
async function dispatchOperations(fi,kind,target,action,payload={}){const c=completion.connections[fi],r=recordFor(fi);if(!c?.url||!c.control||r?.origin!=='gateway')throw Error('Command gateway is not enabled for this factory');if(sourceState(fi).stale||c.error)throw Error('Refresh current factory data before requesting an action');const requestId=globalThis.crypto?.randomUUID?.()||'REQ-'+Date.now()+'-'+Math.random().toString(36).slice(2);const res=await fetch(c.url+'/commands',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json','Idempotency-Key':requestId},body:JSON.stringify({requestId,factory:fi,kind,target,action,payload,requestedAt:new Date().toISOString()}),signal:AbortSignal.timeout(10000)});if(!res.ok)throw Error('Command rejected: HTTP '+res.status);const reply=await res.json();if(!['accepted','executed','rejected'].includes(reply.status)||typeof reply.requestId!=='string'||reply.requestId!==requestId)throw Error('Invalid command receipt; confirm status at the gateway before retrying');eventLog(target+' '+action+' · gateway '+reply.status,'Operations',fi);await refreshConnection(fi);openModal('Gateway command receipt · '+escapeHTML(factories[fi].name),`<p>Request: ${escapeHTML(reply.requestId)}</p><p>Status: <strong>${escapeHTML(reply.status)}</strong></p><p>${escapeHTML(reply.message||'Accepted does not mean executed. Equipment state changes only after the next confirmed source snapshot.')}</p>`);return reply}
async function requestOperationsCommand(fi,kind,target,action,payload={}){try{return await dispatchOperations(fi,kind,target,action,payload)}catch(e){openModal('Action not confirmed',escapeHTML(e.message)+'. No local equipment state was changed.')}}
// Approved files are kept as binary files in IndexedDB, never inserted as HTML.
let documentDB;
function openDocumentDB(){if(documentDB)return documentDB;documentDB=new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(Error('Persistent file storage is unavailable in this browser'));return}const req=indexedDB.open('lifescience-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return documentDB}
async function fileStore(mode,item){const db=await openDocumentDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files',mode==='get'?'readonly':'readwrite'),store=tx.objectStore('files');let req=mode==='get'?store.get(item):mode==='delete'?store.delete(item):store.put(item);req.onsuccess=()=>{if(mode==='get')resolve(req.result)};tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error)})}
function realDocumentCenter(fi=factoryIndex()){const rows=completion.documents.filter(d=>d.factory===fi);openModal('Controlled documents · '+factories[fi].name,`<div class="document-upload"><label>Document title<input id="real-doc-title" maxlength="120" placeholder="User requirements specification"></label><label>Reference ID<input id="real-doc-ref" maxlength="60" placeholder="URS-001"></label><label>Version<input id="real-doc-version" maxlength="30" placeholder="1.0"></label><label>Approval record / approver<input id="real-doc-approval" maxlength="120" placeholder="Approval reference (leave empty if unverified)"></label><label>Area<select id="real-doc-area">${['Factory','Process','Packaging','Quality','Maintenance','Facility'].map(a=>`<option>${a}</option>`).join('')}</select></label><label>PDF or image<input id="real-doc-file" type="file" accept="application/pdf,image/png,image/jpeg"></label>${opButton('Store document',`storeRealDocument(${fi})`)}</div><p class="note">Approval is supplied by your organization and is not certified by this dashboard. Files are stored only in this browser.</p><div class="table-scroll"><table><tr><th>Reference / title</th><th>Version</th><th>Approval</th><th>Actions</th></tr>${rows.map(d=>`<tr><td>${escapeHTML(d.ref)} · ${escapeHTML(d.title)}</td><td>${escapeHTML(d.version)}</td><td>${escapeHTML(d.approval||'Unverified')}</td><td>${opButton('Open',`openRealDocument('${d.id}')`)}${opButton('Remove',`removeRealDocument('${d.id}')`)}</td></tr>`).join('')||'<tr><td colspan="4">No organization documents uploaded.</td></tr>'}</table></div><div id="document-feedback"></div>`);$('#modal').classList.add('wide-modal')}
async function storeRealDocument(fi=factoryIndex()){try{const file=$('#real-doc-file').files[0],title=$('#real-doc-title').value.trim(),ref=$('#real-doc-ref').value.trim(),version=$('#real-doc-version').value.trim();if(!title||!ref||!version||!file)throw Error('Provide title, reference, version and file');if(!['application/pdf','image/png','image/jpeg'].includes(file.type)||file.size>15000000)throw Error('Use a PDF, PNG or JPEG up to 15 MB');const id='DOC-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);await fileStore('put',{id,file});completion.documents.push({id,factory:fi,title,ref,version,approval:$('#real-doc-approval').value.trim(),area:$('#real-doc-area').value,name:file.name,uploadedAt:new Date().toISOString()});saveCompletion();realDocumentCenter(fi)}catch(e){$('#document-feedback').textContent=e.message}}
async function openRealDocument(id){try{const d=completion.documents.find(d=>d.id===id),entry=await fileStore('get',id);if(!d||!entry)throw Error('Document file is unavailable in this browser');const url=URL.createObjectURL(entry.file);openModal(escapeHTML(d.ref+' · '+d.title),`<div class="scope-label">Version ${escapeHTML(d.version)} · ${escapeHTML(d.approval||'Approval unverified')}</div>${entry.file.type==='application/pdf'?`<iframe class="real-document-frame" sandbox src="${url}" title="Uploaded PDF"></iframe>`:`<img class="real-document-image" src="${url}" alt="Uploaded document">`}<div class="actions"><a class="pill" href="${url}" download="${escapeHTML(d.name)}">Download original</a></div>`);$('#modal').classList.add('wide-modal');$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true})}catch(e){openModal('Document unavailable',escapeHTML(e.message))}}
async function removeRealDocument(id){try{await fileStore('delete',id);completion.documents=completion.documents.filter(d=>d.id!==id);saveCompletion();realDocumentCenter()}catch(e){openModal('Document removal failed',escapeHTML(e.message))}}
function siteLayoutCenter(){if(state.factory<0){openModal('Choose a factory layout',factories.map((f,i)=>opButton(escapeHTML(f.name),`state.factory=${i};render();siteLayoutCenter()`)).join(''));return}openModal('Factory layout · '+scopeName(),`<p>Supply a PNG or JPEG of your actual campus layout or a 3D render. Existing building hotspots retain the illustrative positions until you map them.</p><input id="site-layout-file" type="file" accept="image/png,image/jpeg"><label>Layout reference / revision<input id="site-layout-revision" maxlength="100"></label><div class="actions">${opButton('Use site layout','storeSiteLayout()')}${opButton('Restore illustrative layout','resetSiteLayout()')}</div><div id="layout-feedback"></div><h3>Building hotspot positions</h3><p>Percentages from the image’s top-left corner. Use the site drawing to set each area.</p><div class="layout-points">${campusAreas.map((a,i)=>{const p=completion.layouts?.[factoryIndex()]?.points?.[a.id]||{x:50,y:20+i*10};return `<label>${a.name}<input id="layout-x-${i}" type="number" min="0" max="100" value="${p.x}" aria-label="${a.name} X"><input id="layout-y-${i}" type="number" min="0" max="100" value="${p.y}" aria-label="${a.name} Y"></label>`}).join('')}</div>${opButton('Save hotspot positions','saveLayoutPoints()')}`)}
async function storeSiteLayout(){try{const file=$('#site-layout-file').files[0],revision=$('#site-layout-revision').value.trim();if(!file||!['image/png','image/jpeg'].includes(file.type)||file.size>15000000||!revision)throw Error('Provide a PNG/JPEG up to 15 MB and its revision');const id='LAYOUT-'+factoryIndex();await fileStore('put',{id,file});completion.layouts??={};completion.layouts[factoryIndex()]={id,revision,points:completion.layouts[factoryIndex()]?.points||{}};saveCompletion();render();siteLayoutCenter()}catch(e){$('#layout-feedback').textContent=e.message}}
function saveLayoutPoints(){try{const l=completion.layouts?.[factoryIndex()];if(!l)throw Error('Upload a layout first');const points={};campusAreas.forEach((a,i)=>{const x=+$('#layout-x-'+i).value,y=+$('#layout-y-'+i).value;if(!Number.isFinite(x)||!Number.isFinite(y)||x<0||x>100||y<0||y>100)throw Error('Coordinates must be between 0 and 100');points[a.id]={x,y}});l.points=points;saveCompletion();render();siteLayoutCenter()}catch(e){$('#layout-feedback').textContent=e.message}}
function resetSiteLayout(){if(completion.layouts)delete completion.layouts[factoryIndex()];saveCompletion();render();siteLayoutCenter()}
let customLayoutURL='';
async function applySiteLayout(){const fi=factoryIndex(),layout=completion.layouts?.[fi],viewer=document.querySelector('#smart-campus-scene');if(!layout||!viewer)return;try{const entry=await fileStore('get',layout.id);if(!entry||fi!==factoryIndex()||!viewer.isConnected)return;if(customLayoutURL)URL.revokeObjectURL(customLayoutURL);customLayoutURL=URL.createObjectURL(entry.file);viewer.querySelector('img').src=customLayoutURL;viewer.querySelector('img').alt='Organization supplied site layout · '+layout.revision;viewer.querySelectorAll('.smart-building-hotspot').forEach((el,i)=>{const p=layout.points[campusAreas[i].id];if(p){el.style.left=p.x+'%';el.style.top=p.y+'%'}});document.querySelector('.smart-view-options>span').textContent='SITE LAYOUT · '+layout.revision}catch{}}
let weatherOverlayEnabled=false,weatherOverlayGeneration=0;
async function toggleWeatherOverlay(){weatherOverlayEnabled=!weatherOverlayEnabled;const existing=document.querySelector('.map-weather-layer');existing?.remove();if(!weatherOverlayEnabled){weatherOverlayGeneration++;return}await drawWeatherOverlay()}
async function drawWeatherOverlay(){if(!weatherOverlayEnabled||state.tab!=='Overview')return;document.querySelector('.map-weather-layer')?.remove();const generation=++weatherOverlayGeneration,panel=document.createElement('section');panel.className='map-weather-layer';panel.innerHTML='<strong>Weather across factories</strong><small>Loading current conditions…</small>';document.querySelector('#main').appendChild(panel);const rows=await Promise.all(factories.map(async(f,i)=>{try{const c=coordinates[i],res=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${c[0]}&longitude=${c[1]}&current=temperature_2m,wind_speed_10m&timezone=Africa%2FCairo`,{signal:AbortSignal.timeout(10000)});if(!res.ok)throw Error();const data=await res.json();return `<button onclick="selectMapFactory(${i})"><span>${escapeHTML(f.name)}</span><strong>${Number(data.current.temperature_2m).toFixed(1)} °C</strong><small>Wind ${Number(data.current.wind_speed_10m).toFixed(1)} km/h</small></button>`}catch{return `<div>${escapeHTML(f.name)} · Weather unavailable</div>`}}));if(generation!==weatherOverlayGeneration||!weatherOverlayEnabled||!panel.isConnected)return;panel.innerHTML='<div class="row"><strong>Factory weather</strong><button onclick="toggleWeatherOverlay()" aria-label="Close weather overlay">×</button></div>'+rows.join('')+'<small>Open-Meteo · current model conditions · illustrative site coordinates</small>'}
