const facilityBeforeCompletion=facilityView;facilityView=function(){const r=recordFor();if(!r?.facility)return facilityBeforeCompletion();return `<div class="business-strip"><strong>Facility readiness</strong><span>${escapeHTML(r.source)} · ${escapeHTML(r.observedAt)}</span></div><div class="entity-grid">${r.facility.map(m=>`<div class="entity"><strong>${escapeHTML(m.name)}</strong><div class="metric-reading">${m.value} <small>${escapeHTML(m.unit)}</small></div><small>${m.min}–${m.max} ${escapeHTML(m.unit)} · ${m.value>=m.min&&m.value<=m.max?'Within range':'Attention required'}</small></div>`).join('')}</div><div class="analytics-grid">${analyticsChart('Facility conformance','Measures within their supplied operating range',r.facility.map(m=>m.name),r.facility.map(m=>m.value>=m.min&&m.value<=m.max?100:0),'%',{viz:'bullet',target:100})}<section class="panel"><h2>Source and actions</h2><p>${escapeHTML(r.source)} · ${escapeHTML(r.observedAt)}</p><div class="actions">${opButton('Facility alarms','alarmCenter()')}${opButton('Organization documents','realDocumentCenter()')}${opButton('Source record',`inspectOperations(${r.factory})`)}</div></section></div>`};
const qualityBeforeCompletion=quality;quality=function(){const r=recordFor();if(state.factory<0||!r?.quality)return qualityBeforeCompletion();const q=r.quality,c=q.cip,pat=q.pat||[];return `<div class="business-strip"><strong>Quality monitoring</strong><span>${escapeHTML(r.source)} · ${escapeHTML(r.observedAt)} · No video</span></div><div class="analytics-grid source-quality-grid"><section class="panel"><h2>CIP · Cleaning in place</h2>${c?`<div class="row"><strong>${escapeHTML(c.asset)}</strong><span class="pill">${escapeHTML(c.status)}</span></div><p>Recipe ${escapeHTML(c.recipe)} · ${escapeHTML(c.phase)}</p><div class="modal-metrics"><div><small>Temperature</small><h3>${c.temperature} °C</h3></div><div><small>Flow</small><h3>${c.flow} m³/h</h3></div><div><small>Conductivity</small><h3>${c.conductivity} mS/cm</h3></div></div><p>Phase limits: ${c.limits.temperatureMin}–${c.limits.temperatureMax} °C · flow ≥ ${c.limits.flowMin} m³/h · conductivity ≤ ${c.limits.conductivityMax} mS/cm.</p><span class="pill">${c.temperature>=c.limits.temperatureMin&&c.temperature<=c.limits.temperatureMax&&c.flow>=c.limits.flowMin&&c.conductivity<=c.limits.conductivityMax?'Within supplied phase limits':'Quality review required'}</span><p>Completion does not certify validated cleaning.</p>`:'<p>CIP data not supplied for this source.</p>'}<div class="actions">${opButton('Quality documents','realDocumentCenter()')}${opButton('CIP history','sourceCipHistory()')}${opButton('Source record',`inspectOperations(${r.factory})`)}</div></section><section class="panel"><h2>PAT · Product quality</h2><div class="table-scroll"><table><tr><th>Measure</th><th>Reading</th><th>Range</th><th>Status</th></tr>${pat.map(m=>`<tr><td>${escapeHTML(m.name)}</td><td>${m.value} ${escapeHTML(m.unit)}</td><td>${m.min}–${m.max}</td><td class="${m.value>=m.min&&m.value<=m.max?'positive':'warning'}">${m.value>=m.min&&m.value<=m.max?'Within range':'Review'}</td></tr>`).join('')||'<tr><td colspan="4">PAT data not supplied.</td></tr>'}</table></div></section>${analyticsChart('PAT acceptance','Share of supplied measures within range',['Within range','Review'],[pat.filter(m=>m.value>=m.min&&m.value<=m.max).length,pat.filter(m=>m.value<m.min||m.value>m.max).length],'measures',{viz:'donut'})}<section class="panel"><h2>Quality actions</h2><p>Review out-of-range readings with their batch evidence and approved methods. Displayed ranges come from the imported source.</p><div class="actions">${opButton('Quality alarms','alarmCenter()')}${opButton('Batch records',"go('Process')")}${opButton('Export source record','exportOperations()')}</div></section></div>`};
function analyzeThresholdAsset(){const a=assetFor(maint.factory,maint.index),c=conditionFor(maint.factory,maint.index),p=thresholdForecast(c.samples,c.limit),labels=c.samples.map(s=>new Date(s.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}));openModal(escapeHTML(a.id)+' · Threshold forecast',`<div class="scope-label">${escapeHTML(factories[maint.factory].name)} · ${escapeHTML(c.source)}</div>${analyticsChart('Condition evidence',c.label,labels,c.series,c.unit,{target:c.limit,viz:'area'})}<div class="modal-metrics"><div><small>Assessment</small><h3>${p.status}</h3></div><div><small>Estimated threshold crossing</small><h3>${p.hours===0?'Already exceeded':p.hours==null?'Not estimated':p.hours.toFixed(1)+' h'}</h3></div><div><small>Trend fit R²</small><h3>${p.r2==null?'—':p.r2.toFixed(2)}</h3></div></div><p>${p.n?`${p.n} samples · slope ${p.slope.toFixed(3)} ${escapeHTML(c.unit)}/hour · residual error ${p.rmse.toFixed(3)} ${escapeHTML(c.unit)}. Linear 24-hour estimate: ${p.prediction.toFixed(2)} ${escapeHTML(c.unit)}.`:p.note}</p><p>Last sample: ${escapeHTML(c.samples.at(-1)?.time||'not supplied')}. The time-to-threshold and 24-hour horizon are measured from that sample. This is a linear condition-threshold forecast, not equipment remaining useful life or a validated fault diagnosis. Extrapolation can be unreliable when operating conditions change.</p><div class="actions">${opButton('Assign qualified person','assignMaintenanceAsset()')}${opButton('Source record',`inspectOperations(${maint.factory})`)}</div>`);$('#modal').classList.add('wide-modal')}
