const supplyBeforeSources=supplyChainView;supplyChainView=function(){const r=recordFor(),s=r?.supplyChain;if(state.factory<0||!s)return supplyBeforeSources();return `<div class="business-strip"><strong>Supply chain readiness</strong><span>${escapeHTML(r.source)} · ${escapeHTML(r.observedAt)}</span></div><div class="analytics-grid"><section class="panel"><h2>Materials and inventory</h2><div class="table-scroll"><table><tr><th>Material</th><th>On hand</th><th>Coverage</th><th>Status</th></tr>${s.materials.map(m=>`<tr><td>${escapeHTML(m.name)}</td><td>${m.onHand} ${escapeHTML(m.unit)}</td><td>${m.coverageDays} days</td><td>${escapeHTML(m.status)}</td></tr>`).join('')}</table></div></section><section class="panel"><h2>Customer commitments</h2><div class="table-scroll"><table><tr><th>Order</th><th>Customer</th><th>Due</th><th>Units</th><th>Status</th></tr>${s.orders.map(o=>`<tr><td>${o.id}</td><td>${escapeHTML(o.customer)}</td><td>${escapeHTML(o.due)}</td><td>${o.units}</td><td class="${o.atRisk?'warning':'positive'}">${escapeHTML(o.status)}</td></tr>`).join('')}</table></div></section>${analyticsChart('Delivery performance','Source period profile',s.labels,s.deliveryTrend,'%',{viz:'line',target:93})}${analyticsChart('Supplier acceptance','Source period profile',s.labels,s.supplierQualityTrend,'%',{viz:'bullet',target:98})}</div>`};

const metricsBeforeExtraSources=pageMetrics;pageMetrics=function(){const r=recordFor();if(state.factory>=0&&r?.sustainability&&state.tab==='Sustainability'){const s=r.sustainability;return [['Energy cost per unit','EGP '+s.energyCost.at(-1),'Latest source period'],['Water reused',s.waterReuse.at(-1)+'%','Latest source period'],['Carbon footprint',nfmt(s.emissions.reduce((a,b)=>a+b,0))+' tCO2e','Source period total'],['Waste recovery',s.wasteRecovery.at(-1)+'%','Latest source period']]}if(state.factory>=0&&r?.supplyChain&&state.tab==='Supply Chain'){const s=r.supplyChain;return [['On-time delivery',s.delivery+'%','Source measure'],['Inventory coverage',s.inventoryCoverageDays+' days','Source measure'],['Supplier quality',s.supplierQuality+'%','Source measure'],['Orders at risk',s.orders.filter(o=>o.atRisk).length,'Source orders']]}return metricsBeforeExtraSources()};

