const completionRequests=new Set(),dispatchBeforeLock=dispatchOperations;
dispatchOperations=async function(fi,kind,target,action,payload={}){const key=[fi,kind,target,action].join('|');if(completionRequests.has(key))throw Error('This command request is already in progress');completionRequests.add(key);try{return await dispatchBeforeLock(fi,kind,target,action,payload)}finally{completionRequests.delete(key)}};

